CREATE OR REPLACE FUNCTION public.create_community_chat_group(p_id uuid,p_community_id uuid,p_name text,p_description text DEFAULT '',p_visibility text DEFAULT 'public',p_countries_enabled boolean DEFAULT NULL,p_allowed_countries uuid[] DEFAULT NULL,p_cities_enabled boolean DEFAULT NULL,p_allowed_cities uuid[] DEFAULT NULL,p_certification_required boolean DEFAULT NULL,p_gender_restriction genre_enum DEFAULT NULL,p_age_min integer DEFAULT NULL,p_age_max integer DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $fn$ DECLARE v_uid uuid:=auth.uid(); v_id uuid:=COALESCE(p_id,gen_random_uuid()); v_rules public.community_access_rules; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Utilisateur non authentifié'; END IF; IF NOT public.is_community_member(p_community_id) THEN RAISE EXCEPTION 'Vous devez être membre de la communauté pour créer une discussion'; END IF; IF p_name IS NULL OR length(trim(p_name))<2 OR length(trim(p_name))>80 THEN RAISE EXCEPTION 'Nom du groupe invalide'; END IF; IF p_visibility NOT IN ('public','private') THEN RAISE EXCEPTION 'Visibilité invalide'; END IF; SELECT * INTO v_rules FROM public.community_access_rules WHERE community_id=p_community_id; INSERT INTO public.community_salons(id,community_id,name,type,audio_messages_allowed,created_by,visibility,description) VALUES(v_id,p_community_id,trim(p_name),'texte',false,v_uid,p_visibility,COALESCE(trim(p_description),'')); INSERT INTO public.community_salon_access_rules(salon_id,countries_enabled,allowed_countries,cities_enabled,allowed_cities,certification_required,gender_restriction,age_min,age_max) VALUES(v_id,COALESCE(p_countries_enabled,v_rules.countries_enabled,false),COALESCE(p_allowed_countries,v_rules.allowed_countries,'{}'),COALESCE(p_cities_enabled,v_rules.cities_enabled,false),COALESCE(p_allowed_cities,v_rules.allowed_cities,'{}'),COALESCE(p_certification_required,v_rules.certification_required,false),COALESCE(p_gender_restriction,v_rules.gender_restriction),COALESCE(p_age_min,v_rules.age_min),COALESCE(p_age_max,v_rules.age_max)); INSERT INTO public.community_salon_members(salon_id,user_id,role) VALUES(v_id,v_uid,'owner') ON CONFLICT(salon_id,user_id) DO NOTHING; RETURN v_id; END; $fn$; REVOKE ALL ON FUNCTION public.create_community_chat_group(uuid,uuid,text,text,text,boolean,uuid[],boolean,uuid[],boolean,genre_enum,integer,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_community_chat_group(uuid,uuid,text,text,text,boolean,uuid[],boolean,uuid[],boolean,genre_enum,integer,integer) TO authenticated;